// Prepare Drafts: validate rows, compute word count, build the full judge payload.
// String parsing only. No URL class, no external libraries (n8n Code sandbox).

const RUBRIC = `You are a strict content citability judge. You evaluate DRAFT content for how likely AI answer engines (ChatGPT, Claude, Perplexity, Gemini) are to retrieve, quote, and cite it when answering buyer questions.

Score the draft on exactly three dimensions, 0-100 each, using the anchored rubrics below. Grade against the anchors, not against your general impression. Be conservative: a score above 85 must be genuinely rare.

DIMENSION 1: ANSWER STRUCTURE (how extractable are the answers?)
- 90-100: Opens with a direct, standalone answer to the target query within the first two paragraphs. Headers are question-shaped or claim-shaped. Each section leads with its conclusion, then supports it. Any single section could be lifted verbatim as a complete answer.
- 70-89: Answers are present and mostly front-loaded, but at least one key section buries its point mid-paragraph or a header fails to signal what the section answers.
- 50-69: Answers exist but the reader (or a retrieval system) must assemble them from multiple places. Sections build narrative before delivering the point.
- 30-49: Structured like an essay or story. Conclusions arrive at the end. Headers are decorative rather than informative.
- 0-29: No identifiable direct answer to the target query anywhere in the draft.

DIMENSION 2: ENTITY CLARITY (would a lifted passage still identify who and what?)
- 90-100: The brand, product, and core concepts are named and defined in self-contained sentences. Every major section re-anchors the entity by name. Zero passages depend on prior context to resolve \"it\", \"this\", \"the platform\", \"our tool\".
- 70-89: Entities are defined early, but some later sections rely on pronouns or generic references that would be ambiguous if the passage were quoted alone.
- 50-69: The brand is named but never explicitly defined in a standalone sentence, or key concepts are used before they are defined.
- 30-49: Heavy pronoun and generic-reference use. A lifted paragraph would not reliably identify the brand or product.
- 0-29: The entity is essentially anonymous. The content could be about any vendor in the category.

DIMENSION 3: FACTUAL DENSITY (is there anything concrete worth citing?)
- 90-100: Specific numbers, dates, named sources, and verifiable claims appear throughout. Most paragraphs contain at least one concrete, checkable fact. Claims are attributed.
- 70-89: Solid concrete claims in the core sections, but noticeable stretches of unsupported assertion or filler.
- 50-69: A few real data points surrounded by mostly qualitative claims (\"significantly faster\", \"many teams\").
- 30-49: Almost entirely adjectives and unverifiable claims. One or two token statistics.
- 0-29: No concrete, verifiable facts at all.

EVIDENCE REQUIREMENT: For each dimension, quote 1-3 short passages (under 25 words each) from the draft that most influenced your score, and list the specific issues holding the score down. Quotes must be verbatim from the draft. If you cannot quote evidence for a score, lower the score.

FIXES: Return the top 3 fixes ranked by expected impact on the composite score. Each fix must be specific to THIS draft (name the section or passage), not generic advice.

LIFTABLE PASSAGE: Identify the single best existing passage (under 50 words) an AI engine could quote verbatim as a complete answer. If none exists, return an empty string.

Return ONLY a JSON object, no markdown fences, no preamble, with exactly this shape:
{
  \"answer_structure\": {\"score\": 0, \"evidence\": [\"...\"], \"issues\": [\"...\"]},
  \"entity_clarity\": {\"score\": 0, \"evidence\": [\"...\"], \"issues\": [\"...\"]},
  \"factual_density\": {\"score\": 0, \"evidence\": [\"...\"], \"issues\": [\"...\"]},
  \"top_fixes\": [{\"fix\": \"...\", \"dimension\": \"answer_structure|entity_clarity|factual_density\", \"impact\": \"high|medium|low\"}],
  \"liftable_passage\": \"...\"
}`;

const out = [];

for (const item of $input.all()) {
  const row = item.json;
  const draft = String(row.draft_text || '').trim();
  if (!draft) continue; // skip empty rows

  const contentId = String(row.content_id || '').trim() || 'row-' + (out.length + 1);
  const title = String(row.title || '').trim();
  const brand = String(row.brand || '').trim();
  const targetQuery = String(row.target_query || '').trim();
  const wordCount = draft.split(/\s+/).filter(Boolean).length;

  const userPrompt =
    'TARGET QUERY this draft is meant to answer: ' + (targetQuery || '(not provided)') + '\n' +
    'BRAND the draft represents: ' + (brand || '(not provided)') + '\n' +
    'DRAFT TITLE: ' + (title || '(untitled)') + '\n\n' +
    'DRAFT CONTENT:\n"""\n' + draft + '\n"""';

  out.push({
    json: {
      content_id: contentId,
      title: title,
      brand: brand,
      target_query: targetQuery,
      word_count: wordCount,
      payload: {
        model: 'gpt-4o-mini',
        temperature: 0,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: RUBRIC },
          { role: 'user', content: userPrompt }
        ]
      }
    }
  });
}

if (out.length === 0) {
  throw new Error('No rows with draft_text found in the content tab. Add at least one draft and re-run.');
}

return out;

// Parse & Score: parse judge JSON, clamp scores, compute weighted composite,
// assign verdict, flatten fixes. String ops only.

const WEIGHTS = { answer_structure: 0.4, entity_clarity: 0.3, factual_density: 0.3 };
const src = $('Build Judge Payload').item.json;

let raw = '';
try {
  raw = $json.choices[0].message.content || '';
} catch (e) {
  throw new Error('Unexpected API response shape for ' + src.content_id + ': ' + JSON.stringify($json).slice(0, 300));
}

// Strip accidental markdown fences without regex backtracking surprises
let cleaned = raw.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
}

let judged;
try {
  judged = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Judge returned unparseable JSON for ' + src.content_id + '. First 300 chars: ' + cleaned.slice(0, 300));
}

function clamp(n) {
  const x = Number(n);
  if (!isFinite(x)) return 0;
  return Math.max(0, Math.min(100, Math.round(x)));
}

const dims = {};
for (const d of Object.keys(WEIGHTS)) {
  const block = judged[d] || {};
  dims[d] = {
    score: clamp(block.score),
    evidence: Array.isArray(block.evidence) ? block.evidence : [],
    issues: Array.isArray(block.issues) ? block.issues : []
  };
}

const composite = Math.round(
  dims.answer_structure.score * WEIGHTS.answer_structure +
  dims.entity_clarity.score * WEIGHTS.entity_clarity +
  dims.factual_density.score * WEIGHTS.factual_density
);

let verdict = 'rework';
if (composite >= 80) verdict = 'publish';
else if (composite >= 60) verdict = 'revise';

const fixes = Array.isArray(judged.top_fixes) ? judged.top_fixes.slice(0, 3) : [];
const fixesFlat = fixes
  .map((f, i) => (i + 1) + '. [' + String(f.impact || 'n/a') + '] ' + String(f.fix || '').trim())
  .join(' | ');

const issuesFlat = Object.keys(dims)
  .map(d => dims[d].issues.length ? d + ': ' + dims[d].issues.join('; ') : '')
  .filter(Boolean)
  .join(' || ');

return {
  json: {
    run_date: new Date().toISOString().slice(0, 10),
    content_id: src.content_id,
    title: src.title,
    target_query: src.target_query,
    word_count: src.word_count,
    answer_structure: dims.answer_structure.score,
    entity_clarity: dims.entity_clarity.score,
    factual_density: dims.factual_density.score,
    citability_score: composite,
    verdict: verdict,
    top_fixes: fixesFlat,
    liftable_passage: String(judged.liftable_passage || '').trim(),
    issues: issuesFlat
  }
};

// Extract Article Text: convert fetched HTML into clean, judge-ready text.
// String ops only. No URL class, no external libraries (n8n Code sandbox).

const src = $('Check Draft Text Presence').item.json;
let html = '';
if (typeof $json.data === 'string') html = $json.data;
else if (typeof $json.body === 'string') html = $json.body;
else html = String($json.data || '');

if (!html || html.length < 500) {
  throw new Error('Fetch for ' + (src.page_url || 'row') + ' returned almost no HTML. The page may be blocked or JS-rendered. Paste the text into draft_text instead.');
}

// 1. Remove non-content blocks entirely
let t = html
  .replace(/<!--[\s\S]*?-->/g, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
  .replace(/<iframe[\s\S]*?<\/iframe>/gi, ' ');

// 2. Grab page title before narrowing
let pageTitle = '';
const tMatch = t.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
if (tMatch) pageTitle = tMatch[1].replace(/\s+/g, ' ').trim();

// 3. Isolate the main content region: article > main > body
function firstBlock(source, tag) {
  const m = source.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'i'));
  return m ? m[1] : '';
}
let core = firstBlock(t, 'article') || firstBlock(t, 'main') || firstBlock(t, 'body') || t;

// 4. Strip chrome inside the content region
for (const tag of ['nav', 'header', 'footer', 'aside', 'form', 'button', 'select']) {
  core = core.replace(new RegExp('<' + tag + '[\\s\\S]*?<\\/' + tag + '>', 'gi'), ' ');
}

// 5. Convert structure to markdown-ish text so the judge still sees it
core = core
  .replace(/<h1[^>]*>/gi, '\n\n# ').replace(/<h2[^>]*>/gi, '\n\n## ')
  .replace(/<h3[^>]*>/gi, '\n\n### ').replace(/<h4[^>]*>/gi, '\n\n#### ')
  .replace(/<h5[^>]*>/gi, '\n\n##### ').replace(/<h6[^>]*>/gi, '\n\n###### ')
  .replace(/<\/h[1-6]>/gi, '\n')
  .replace(/<li[^>]*>/gi, '\n- ').replace(/<\/li>/gi, '')
  .replace(/<tr[^>]*>/gi, '\n').replace(/<\/t[dh]>/gi, ' | ').replace(/<t[dh][^>]*>/gi, '')
  .replace(/<\/table>/gi, '\n')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(p|div|section|blockquote|ul|ol|figure)>/gi, '\n');

// 6. Strip all remaining tags, decode common entities, collapse whitespace
core = core.replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#0?39;/g, "'")
  .replace(/&#8217;/g, "'").replace(/&#8216;/g, "'").replace(/&#8220;/g, '"')
  .replace(/&#8221;/g, '"').replace(/&#8211;/g, '-').replace(/&#8212;/g, '-')
  .replace(/&mdash;/gi, '-').replace(/&ndash;/gi, '-').replace(/&hellip;/gi, '...')
  .replace(/[ \t]+/g, ' ')
  .replace(/ ?\n ?/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// 7. Sanity check and size cap (Sheets cell limit is 50,000 chars)
const wordCount = core.split(/\s+/).filter(Boolean).length;
if (wordCount < 200) {
  throw new Error('Only ' + wordCount + ' words extracted from ' + (src.page_url || 'page') + '. The page is likely JS-rendered or blocked. Paste the text into draft_text instead.');
}
if (core.length > 45000) {
  core = core.slice(0, 45000) + '\n\n[truncated for scoring]';
}

return {
  json: {
    content_id: src.content_id,
    title: String(src.title || '').trim() || pageTitle,
    brand: src.brand,
    target_query: src.target_query,
    page_url: src.page_url,
    draft_text: core
  }
};
